INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, part, category, description, responder, resolver, resolution, status, created_by) VALUES ('cmp-c6fcd674', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2024-01-30', '황금옥', '데스크', '데스크', '진)보철 관련', '강혜란', '강혜란', '하악은 임플란트를 하고,상악은 기존틀니를 쓰시는데 하악이 튼튼해지니 상악 틀니가 덜그덕거리고 하여 식사가 잘 안되고 잇몸도 아프신거 같다. 치료 많이고생 많이 하셨는데 편안하게 잘쓰셔야 하는데 ~~ 이게 계속 불편한 상황이시면 상악 틀니를 다시하던지 해야할것 같다고 안내드림. 상악틀니는 대략 8년정도 사용하셨다고 하심. 아드님께도 동일하게 설명을 드렸으나 어머님 힘들어 하시니 속상해서 계속 말씀하심. -혜란-', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, part, category, description, responder, resolver, resolution, status, created_by) VALUES ('cmp-3695ad27', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2024-01-31', '김대호', '전화', '전화', '데)수납 관련', '윤다인', '강혜란', '현재 치료하신 부분만 상세히 비용안내 다시 안내드림.해당 비용만 들으시고 그냥 뚝 끊어 버시셔서 내일쯤 다시 담당실장님 전화드려야 할듯~~', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
