INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, part, category, description, responder, resolver, resolution, status, created_by) VALUES ('cmp-32b82fec', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-03-13', '박하', '기타', '기타', '진)기타', '박설희', NULL, '보철물 탈락으로 위협...소리치심...컴플레인너무심하게하심ㅠㅠ', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, part, category, description, responder, resolver, resolution, status, created_by) VALUES ('cmp-7a5fbc7c', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-03-13', '이은진', '진료실', '진료실', '진)기타', '박설희', NULL, '신환분 당접 당일 검진 후 사랑니 발치불가로 컴플레인하심. 차트삭제까지 요청하셔서 기록없음...(정말 많이 이상하셨음,,)', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-d7ea2c2c', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-06-23', '김서하B/140525', '장치를 잘 끼지 않아서 퍼스트 진행이 안됨.기간도 얼마 남지 않고 하여 브라켓으로 장치 변동 있음.고민해보시고 전화주시기로함.', '임지원/박희주/강혜란', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-51f918eb', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-06-23', '박하은E/070507', '장치를 잘끼지 않은상태로 2년 넘는 시간동안 교정 진행.진행은 거의 안됨.서울에서 내원.브라켓으로 변경 안내드릴예정. 고민후 연락 주시기로함.', '김민규/전유진/강혜란', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-35197d83', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-06-23', '장경섭/810729', '잇몸염증이 있고 한데 왜 돈 얘기부터 하는건지..지금도 마비온게 다 회복되지 않아서 힘든데..돈을 내라고 하면 낼꺼다, 근데 치료를 원하는데 돈예기부터 하는건 기분이 너무 나쁘다.다시 설명드리고 치료 이어서 진행하심.', '문석준/권효정/강혜란', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-b3ea98a6', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-06-24', '강성기/670314', '신경치료 후 3개월 만에 내원(2회 당일 연락없이 취소/문자 여러번 드렸음). 전부터 예약잡기 힘들고 원장님 변경으로 컴플레인 호소 하셨으나 진단변경으로 이부분에 대해 불편감 호소 하시고 본원과는 맞지 않은 것 같다고 다른병원 가보시겠다고 하심.', '문석준->김민수/지민아/한혜림', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
