INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-affd245c', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-08-23', '안영선 (650625)', '#37 - 수술시 다 설명해주면서 했는데 비용이 드는 뼈이식은 왜 한다는 소리도 없이 했냐? 뼈이식을 안하고 했다한다고 오해하심. 아니라고 설명드렸으나 컴플레인 많이함. 내원 시 다시 설명필요함.', '홍서영', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
