INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-6e550b0c', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2025-09-25', '오하람(06)', '교정관련 컴플레인 보호자(모) - 앞니 돌출로 인해 교정을 시작한건데 교정 끝난지 얼마 되지도 않은거같은데 다시 앞니가 돌출된거같아요 교정기간동안도 계속 시간을 내서 진료를 보러갔던건데 이번에 유지장치도 재부착하고나서 치아가 시린부분이 생기고 또 다시 시간을 내서 진료를 보러가야하는 부분도 아이가 스트레스받아하고, 시간내서 왔다갔다하는것도 힘들고 속상하다고하심', '최지현', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
