INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-94bd9f12', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-01-06', '송병철(71)', '임플란트 픽스쳐 2번 fail,본뜨는날 fail되서 화가 많이 나셨고 아내분 전화로 원장님 통화 희망하심,최종훈원장님께 부탁드려 원장님께서 보호자분과 통화 진행', '박설희', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-a4c69359', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-01-07', '이경화(81)', '진료시마다 대기 시간 및 진단이 정확하지않고 설명이 부족한거 같다고 하심,진료시마다 불편했던점 죄송하다고 말씀드림,수납 관련해서도 남은 금액 문의하셔서 그동안 수납 내역 뽑아서 안내드림', '박설희', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-96efbd01', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-01-09', '송유자(60)', '환자분 c.c 통증으로 내원하셨는데 상담 후 점심시간으로 바로 치료 진행어려워 2시 내원안내드렸으나 막무가내로 지금 치료해달라고 하심,원장님 확인후 바로 치료 진행어려운 부분 다시 양해부탁드렸으나 상담 먼저해서 치료못한거 아니냐,당장 치료해줘라 컨플레인하심', '노지은/박설희', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
