INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-e5a9ad93', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-03-03', '김도현W(991219)', '사랑니 발치 후 설측골 파절 후 의료과실아니냐며 본인이 진료비를 내야하는게 맞는지 컴플레인 하심. 발치동의서에 이런 내용 없었다고 하셔서 여러가지 관련 내용 확인시켜드리고 있을 수 있는 과정인 부분, 보험진료비는 내셔야 함 강조드림. --->디자인팀에 발치동의서 내용 수정 요청함/혜림', '한혜림', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
