INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-b9efb65c', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-03-12', '차재일 (540622)', '대기실에서 다른 환자분이 통화중이신거 듣기 싫다고 가서 환자분 통화 제지해달라고 말씀하심 환자분 통화 목소리가 그렇게 크거나 하신건 아니셨음,, 이미 통화중이시고 차재일님은 바로 들어가실 수 있는 상황이라 바로 모신다고 설명드리고 안쪽으로 모셨으나 가서 말하면 되는걸 왜 자기가 기다리는동안 통화내용은 듣고 있어야 하냐고 하시면서 진료 들어가심,,,,/다인', '윤다인', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-c19db472', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-03-12', '천소희(750902)', '스케일링받으시고 불만있으심', '윤다인', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-af1046d3', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-03-13', '이은진(951209)', '환자분 접수할때부터 신분증 확인으로 기분 나빠하심 + 당일접수후 대기 2시간하셨다고함(정확하게는 70분..) + 당일 강원장님 예약 많고 다른 원장님들도 예약 많아서 발치 어렵고 예약 잡아드리겠다 설명드렸더니 지인 소개로 왔는데 그분이 치과로 전화하셨을때 발치해주겠다고 얘기 들었다고함. (접수했을때도 당일 발치는 어려울 수 있음 설명고지함) 진료실 체어에서 전화통화하면서도 언성 높이면서 통화하시고 엄청 화내심. 파노라마 + 구내포토 + 개인정보 차트 다 삭제해달라고하심', '최수진', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
INSERT OR IGNORE INTO complaints (id, hospital_id, complaint_date, patient_name, description, responder, status, created_by) VALUES ('cmp-bg-6b3d4542', '34653f75-cb75-4b73-b52c-d5675c83bb9f', '2026-03-13', '박하(91)', '크라운 탈락으로 컨플레인하심,본원믿고 원장님 생명의 은인이라고 생각했는데 배신감이 든다고 하심,계속 흥분하셔서 원장님 뵙고 크라운 탈락이유 설명드림(환불처리해드림)', '박설희', 'resolved', '34a05d21-c7db-4a95-9b10-7a721b331dec');
